-- ---------------------------------------------------------------------------
-- Azshara Crater (map 37) -- map markers for the quests fixed on 2026-09-11
-- ---------------------------------------------------------------------------
-- Same shape as 2026_07_14_01_dc_azshara_crater_quest_pois_areas.sql: each
-- objective is a rectangle around its source creatures' live spawns (+/- 40 yd),
-- the turn-in is a small rectangle at the ender (+/- 20 yd), WorldMapAreaId 613.
-- Collection quests used to mark the quest giver as the objective; they now mark
-- the creatures that drop the item (2026_09_11_03 / 2026_09_11_04), and 300407
-- marks the Cooking vendors.
--
-- Every INSERT is guarded on a live spawn existing, so running this BEFORE the
-- Felmusk satyrs are spawned leaves 300300/300301 with only a turn-in marker.
-- Re-run it after spawning -- it deletes and rebuilds only these ten quests.
-- POI ids are fixed per quest (objectives first, turn-in last), so a skipped
-- objective leaves a gap instead of renumbering the others.
--
-- Apply, then restart (quest POIs have no .reload command).
-- ---------------------------------------------------------------------------

DELETE FROM `quest_poi` WHERE `QuestID` IN (300107, 300207, 300300, 300301, 300307, 300407, 300507, 300706, 300804, 300805);
DELETE FROM `quest_poi_points` WHERE `QuestID` IN (300107, 300207, 300300, 300301, 300307, 300407, 300507, 300706, 300804, 300805);

-- Quest 300107 (Hides Against the Cold: Mangy Wolf)

-- Quest 300207 (Dust of the Fallen: Dreadbone Skeleton)

-- Quest 300300 (A Test of Steel: Felmusk Satyr / Felmusk Rogue (hand-spawned))

-- Quest 300301 (Ten Cursed Horns: Felmusk satyrs (hand-spawned))

-- Quest 300307 (Beads of the Thistlefur: Thistlefur)

-- Quest 300407 (Rations for the Tide-Guard: Cooking vendors at Thalindra's camp)

-- Quest 300507 (Feathers of the Thunderhead: Thunderhead Hippogryph / Skystormer)

-- Quest 300706 (Orders in the Dark: Kil'sorrow Cultist)

-- Quest 300804 (Relics of the Sanctum: Skeletal Craftsman / Moonrest Highborne)

-- Quest 300805 (Unbind the Phantoms: Moonrest Highborne)
